SELECT d.d_year, s.s_store_name, SUM(ss.ss_net_paid) AS total_sales, COUNT(DISTINCT sr.sr_ticket_number) AS total_returns, (SELECT s2.s_manager FROM store s2 WHERE s2.s_store_id = 'AAAAAAAAEBAAAAAA') AS manager_name FROM store_sales ss JOIN date_dim d ON ss.ss_sold_date_sk = d.d_date_sk JOIN store s ON ss.ss_store_sk = s.s_store_sk JOIN store_returns sr ON sr.sr_ticket_number = ss.ss_ticket_number WHERE d.d_year = 1928 GROUP BY d.d_year, s.s_store_name HAVING d.d_year = 1922
